      {
        "id": "yields_high_off_but_rolling_over",
        "label": "10Y 5.15 距区间高 16bp 仍判 off，但连续两周周线回落：这次可能是真的见顶",
        "text": "yields_high 锚维持 off——10Y 收 5.15(10-19)，区间内最高 5.31，按「收盘 ≥ 区间高 × 0.999(5.305)」的机械定义不成立，且距离由上一期的 10bp 拉大到 16bp。但「锚 off」在这两期的含义不一样：上一期是「贴着顶没创高」(水平 5.21、月 +25bp)，本期是「从顶上退下来了」(5.15、月 +21bp、**周 -9bp、连续第二周回落**)。所以这一处必须显式写清楚：off 不代表长端压力缓解，也不代表压力升级，它只说明「没有创新高」；方向要看周线和拆解。本期拆解给出了一个方向性的新细节：周线名义 -9bp 由实际利率(TIPS 2.80%、周 -11bp)贡献，而 BEI 周 **+2bp**——上一期这里写的是「若 10Y 回落的同时 BEI 走高，那是『实际利率见顶、通胀预期接棒』，性质完全反转」，本期第一次出现这个组合。但反证同样硬：10Y 仍在 94 分位、30Y 5.48、5Y 4.94 全在 4.9 上方，月线 +21bp；ACM 期限溢价虽降到 0.9857 仍处高位；10/27 加息定价 82%、2Y 4.77 高出政策上限 77bp。所以准确表述是「长端可能正在筑顶，但只成立了两周」。裁决点：若 10Y 继续回落至 4.90 下方且 BEI 同步走高，本轮定性由「实际利率冲击」改为「通胀预期接棒」，对高久期资产的含义完全不同(前者杀估值，后者杀利润率)；若 10Y 重回 5.25 上方并收在 5.31 之上，则锚转 on，本轮定性为利率事件再升级。",
        "anchor": "yields_high"
      }
